function wbBootHidden() { try { window.__wbLoadHide && window.__wbLoadHide(); } catch (_) {} }




let _wbBootTipStop = null;
(function wbBootWaitGuard() {
  try {
    if (typeof document === 'undefined' || !document.body) return;
    window.__wbBooted = false;
    const banner = document.createElement('div');
    banner.className = 'wb-top-spin';
    banner.style.display = 'none';
    banner.innerHTML = '<i></i><span>工作台还在装载中，再等几秒钟，稍等一下…</span>';
    document.body.appendChild(banner);
    const onClick = (ev) => {
      if (window.__wbBooted) return;
      const t = ev.target;
      if (t && t.closest && t.closest('a[href]')) return;   
      ev.preventDefault(); ev.stopPropagation();
      banner.style.display = 'flex';
      clearTimeout(_wbBootTipStop);
      _wbBootTipStop = setTimeout(() => { banner.style.display = 'none'; }, 1600);
    };
    document.addEventListener('click', onClick, true);
    window.__wbBootGuardOff = function () {
      window.__wbBooted = true;
      try { document.removeEventListener('click', onClick, true); } catch (_) {}
      clearTimeout(_wbBootTipStop);
      banner.remove();
    };
  } catch (_) {}
})();

 
function wbSpin(text) {
  let el = null;
  try {
    el = document.createElement('div');
    el.className = 'wb-top-spin';
    const ico = document.createElement('i');
    const sp = document.createElement('span');
    sp.textContent = text || '正在加载，稍等一下…';
    el.appendChild(ico); el.appendChild(sp);
    document.body.appendChild(el);
  } catch (_) { el = null; }
  return function () { try { if (el) el.remove(); } catch (_) {} };
}




function wbLazyThen(fn) {
  const L = window.__wbLazy;
  if (!L) { fn(); return; }                       
  if (!L.done.length && !L.failed()) {            
    const stop = wbSpin('正在下载获客／灌水的功能文件，稍等一下…');
    L.wait().then(() => {
      stop();
      if (L.failed()) {
        try { toast('获客／灌水的功能文件没下载上，刷新一下页面再试', 'err'); } catch (_) {}
        return;
      }
      fn();
    });
    return;
  }
  L.wait().then(() => {
    if (L.failed()) {
      try { toast('获客／灌水的功能文件没下载上，刷新一下页面再试', 'err'); } catch (_) {}
      return;
    }
    fn();
  });
}





function wbGate(name, fn) {
  const P = window.__wbPacks && window.__wbPacks[name];
  if (!P || typeof P.go !== 'function') { fn(); return; }
  const label = (window.__wbLabel && window.__wbLabel[name]) || name;
  if (!P.started) {
    try { toast('第一次打开「' + label + '」要补下载这一页，稍等一下', 'info'); } catch (_) {}
  }
  const stop = (!P.done.length && !P.failed) ? wbSpin('正在加载「' + label + '」这一页…') : null;
  P.go().then(() => {
    if (stop) stop();
    if (P.failed) {
      try { toast(label + '的功能文件没下载上，刷新一下页面再试', 'err'); } catch (_) {}
      return;
    }
    fn();
  });
}

 
