async function npGenLongform(container, opts) {
  const w = npS(); if (!w || w.longBusy) return;
  const o = opts || {};
  const isL = npIsL(w);                       
  const isLine = npIsLongLine(w);             
  if (isLine) npLongCollect(w, container || npActiveC());   
  const copy = String(isL ? (w.lSeed || '') : '').trim() || String((w.draft && w.draft.content) || '').trim();
  if (!copy) { if (typeof toast === 'function') toast(isL ? '底子空着 AI 也能从零写，但主题至少敲一句——回上一屏补主题' : '长文要有成稿打底——先把正文整出来', 'error'); if (isL && !String(w.lTopic || '').trim()) return; }
  if (isL && !String(w.lTone || '').trim()) { if (typeof toast === 'function') toast('先选腔——科普还是人设，AI 要知道按哪个调调写', 'error'); return; }
  const stale = !!String(w.longform || '').trim() && String(w.longSrc || '') !== copy;
  const prev = (isLine && (o.fresh || stale)) ? '' : String(w.longform || '');
  w.longBusy = true; w.longError = '';
  if (isLine) { if (npS() === w) await npWizRender(container); }
  else npLongPaint(container);
  const stopWait = npWaitInto(container, 'npLongWait', 'AI 正在把这篇排成长文', 'notelongform', () => npS() === w && (isL ? Number(w.lStep || 0) === 1 : (isLine ? w.step === 5 : w.step === 4)));
  try {
    const r = await chrome.runtime.sendMessage({
      action: 'genNoteLongform',
      data: {
        platform: npPid(w),
        line: isL ? String(w.lTone || 'k') : (npIsD(w) ? 'd' : 'k'),
        title: isL ? String(w.lTopic || '') : (_npNote && _npNote.title ? _npNote.title : (((w.draft && w.draft.titles) || [])[0] || '')),
        content: copy || String((w && w.lTopic) || ''),
        prev,
        sellPoint: npSellPointStr(),
        people: (w.chosenPeople || []).map(p => ({ name: (p && p.name) || '' })),
        noteStyle: w.noteStyle || null,
      },
    });
    if (!r || r.ok === false || !r.script) throw new Error((r && r.error) || 'AI 没给出长文，点「✨ 出长文」再试');
    w.longform = String(r.script);
    w.longSrc = copy;   
  } catch (e) { w.longError = String((e && e.message) || e); }
  stopWait();
  w.longBusy = false;
  if (npS() === w) {
    if (isL) npLRender(container);
    else if (isLine) await npWizRender(container);
    else npLongPaint(container);
    if (w.longform) await npArchiveSave(w);   
  }
}




async function npDFinishBase(path) {
  const w = _npWiz;
  if (!w) return null;
  const copy = String((w.draft && w.draft.content) || '').trim();
  if (!copy) { if (typeof toast === 'function') toast('先把正文整出来——改稿页是空的', 'error'); return null; }
  w.voice = copy;          
  w.path = path;
  if (!w.arId) w.arId = npNoteId();
   
  await npArchiveSave(w, path === 'video' ? '' : '代发');
  const n = await npArFindById(w.arId);
  if (!n) { if (typeof toast === 'function') toast('这篇还没进档案——先点「💾 保存」再走出口', 'error'); return null; }
  return n;
}



