function npcFmt(x) { x = Math.max(0, Math.round(Number(x) || 0)); return Math.floor(x / 60) + ':' + String(x % 60).padStart(2, '0'); }
function npcMaxLen(secs) { return Math.max(8, Math.round(secs * 4.5)); }   
