async function npWizRender(container) {
  if (!_npWiz) return;
   
  if (npIsL(_npWiz)) { npLRender(container); return; }
  if (npIsI(_npWiz)) {
    
    if (_npWiz.step === 0 && !_npIpCard && !_npWiz.loading) await npLoadIpCard();
  } else if (npIsK(_npWiz)) {
    
    if (_npWiz.step === 0 && !_npWiz.kbLoaded && !_npWiz.loading) { await npLoadSellPoints(container); return; }
  } else if (_npWiz.step === 0 && !_npWiz.sellPoints.length && !_npWiz.loading) { await npLoadSellPoints(container); return; }
  
  const npNoPre = npIsK(_npWiz) || npIsI(_npWiz) || npIsDStory(_npWiz);
  if (!npNoPre && _npWiz.step === 1 && !_npWiz.people && !_npWiz.peopleError && !_npWiz.loading) { await npLoadPeople(container); return; }
  if (!npNoPre && _npWiz.step === 2 && !_npWiz.topics && !_npWiz.topicError && !_npWiz.loading) { await npLoadTopics(container); return; }
  
  if (!npNoPre && _npWiz.step === 2 && _npWiz.chosenTopicIdx < 0 && (_npWiz.topics || []).length) _npWiz.chosenTopicIdx = 0;
  npStepBar(container);
  renderStep(container);
  npNav(container, navForStep());
  npCfgEmbedPaint();
}

 
async function npLoadKbEntries() {
  try {
    const r = await _diagSay('getKnowledgeBase');
    const list = (r && r.entries) || [];
    _npWiz.kbEntries = list
      .filter(e => e && e.isActive !== false && (String(e.title || '').trim() || String(e.content || '').trim()))
      .map(e => ({
        id: String(e.id || ''),
        title: String(e.title || '').trim(),
        category: String(e.category || '').trim(),
        content: String(e.content || ''),
        tags: Array.isArray(e.tags) ? e.tags.map(t => String(t).trim()).filter(Boolean) : [],
      }));
  } catch (_) { _npWiz.kbEntries = []; }
  _npWiz.kbLoaded = true;
}




let _npUsage = { sell: {}, kb: {} };
async function npUsageIndex() {
  const sell = {}, kb = {};
  const push = (map, key, topic) => {
    if (!key || !topic) return;
    const a = map[key] || (map[key] = []);
    if (a.indexOf(topic) < 0) a.push(topic);
  };
  try {
    const list = await npNotesAll();
    list.forEach(n => {
      if (!n) return;
      const tp = String(n.topic || '').trim();
      (n.sellPoints || []).forEach(p => push(sell, String((p && p.point) || '').trim(), tp));
      (n.kb || []).forEach(e => {
        push(kb, String((e && e.id) || '').trim(), tp);
        push(kb, String((e && e.title) || '').trim(), tp);
      });
    });
  } catch (_) {}
  _npUsage = { sell: sell, kb: kb };
  return _npUsage;
}
 
