let _npMotifs = [];                       
 
function npMotifShape(raw) {
  if (typeof VisualMotif === 'undefined') return [];
  return (Array.isArray(raw) ? raw : []).map(x => VisualMotif.entry(x)).filter(Boolean).slice(0, 24);
}
 
function npMotifTip(m) {
  if (!m) return '';
  return [m.take, m.cast ? '怎么把这段文案变成画面：' + m.cast : '', m.forbid ? '这样算不合格：' + m.forbid : '', m.need ? '要什么料：' + m.need : '']
    .filter(Boolean).join('\n');
}
function npMotifAll() {
  if (typeof VisualMotif === 'undefined') return [];
  try { return VisualMotif.all(_npMotifs); } catch (_) { return []; }
}
function npMotifOpts() { return npMotifAll().map(x => x.k); }
function npMotifOf(k) {
  const list = npMotifAll().filter(x => x.k === String(k || '').trim());
  return list[0] || null;
}
 
function npMotifIsBuilt(k) {
  const s = String(k || '').trim();
  if (typeof VisualMotif === 'undefined') return false;
  return (VisualMotif.VISUAL_MOTIFS || []).some(x => x.k === s);
}
 
function npMotifNeed(k) { const m = npMotifOf(k); return m ? m.need : ''; }
async function npLoadImgMotifs() {
  try { const c = await readConfigPlain(); _npMotifs = npMotifShape(c && c.imgMotifs); }
  catch (_) { _npMotifs = []; }
  return _npMotifs;
}
async function npSaveImgMotifs(list) {
  const cfg = await readConfigPlain();
  cfg.imgMotifs = npMotifShape(list);
  await chrome.storage.local.set({ config: (typeof DataPrivacy !== 'undefined') ? await DataPrivacy.lockConfig(cfg) : cfg });
  _npMotifs = cfg.imgMotifs;
}





const NP_STAGES = ['cold', 'grow', 'mature'];
function npStagePlanDefaults(stage) {
  if (stage === 'cold') return { k: '常发', d: '主发', c: '少发', kbCats: ['免费测漏', '材料保真'], drainCats: ['🔥 热点', '😹 热梗'] };
  if (stage === 'grow') return { k: '主发', d: '常发', c: '常发', kbCats: ['自有施工队'], drainCats: ['🧭 生活场景', '💢 情绪'] };
  if (stage === 'mature') return { k: '常发', d: '常发', c: '主发', kbCats: ['质保十年'], drainCats: ['🏘 本地感悟', '🎯 被生活打了一下'] };
  return { k: '常发', d: '主发', c: '少发', kbCats: [], drainCats: [] };
}
 
async function npStagePlanRead() {
  try {
    const c = await readConfigPlain();
    const sp = (c && c.product && c.product.stagePlan) || {};
    const out = {};
    const norm = (v, def) => ['主发', '常发', '少发'].indexOf(String(v || '')) >= 0 ? v : def;
    NP_STAGES.forEach(stage => {
      const cur = sp[stage] && typeof sp[stage] === 'object' ? sp[stage] : {};
      const def = npStagePlanDefaults(stage);
      out[stage] = {
        k: norm(cur.k, def.k),
        d: norm(cur.d, def.d),
        c: norm(cur.c, def.c),
        kbCats: Array.isArray(cur.kbCats) ? cur.kbCats.map(x => String(x || '').trim()).filter(Boolean).slice(0, 12) : def.kbCats,
        drainCats: Array.isArray(cur.drainCats) ? cur.drainCats.map(x => String(x || '').trim()).filter(Boolean).slice(0, 12) : def.drainCats,
      };
    });
    return out;
  } catch (_) {
    const out = {};
    NP_STAGES.forEach(stage => { out[stage] = npStagePlanDefaults(stage); });
    return out;
  }
}
 
async function npStagePlanSave(stagePlan) {
  const safe = await npStagePlanRead();   
  if (stagePlan && typeof stagePlan === 'object') {
    NP_STAGES.forEach(stage => {
      const cur = stagePlan[stage];
      if (!cur || typeof cur !== 'object') return;
      if (['主发', '常发', '少发'].indexOf(cur.k) >= 0) safe[stage].k = cur.k;
      if (['主发', '常发', '少发'].indexOf(cur.d) >= 0) safe[stage].d = cur.d;
      if (['主发', '常发', '少发'].indexOf(cur.c) >= 0) safe[stage].c = cur.c;
      if (Array.isArray(cur.kbCats)) safe[stage].kbCats = cur.kbCats.map(x => String(x || '').trim()).filter(Boolean).slice(0, 12);
      if (Array.isArray(cur.drainCats)) safe[stage].drainCats = cur.drainCats.map(x => String(x || '').trim()).filter(Boolean).slice(0, 12);
    });
  }
  const c = await readConfigPlain();
  const next = Object.assign({}, c, {
    product: Object.assign({}, (c && c.product) || {}, { stagePlan: safe }),
  });
  await writeConfigPlain(next);
  return safe;
}













