async function npAsKindStateWrite(v) {
  try { await chrome.storage.local.set({ [NP_AS_KIND_KEY]: v }); } catch (_) {}
}
 
function npAsKindV(st, k) {
  if (!npAssetKindOf(k)) return '';
  const o = st && st.own && st.own[k];
  if (o === 'need' || o === 'no' || o === 'ask') return o;
  const one = st && st.kinds && st.kinds[k];
  if (one && (one.v === 'need' || one.v === 'no' || one.v === 'ask')) return one.v;
  return npAsGrayKind(k) ? 'gray' : 'ask';
}
function npAsGrayKind(k) {
  const x = npAssetKindOf(k);
  return !!(x && x.gray);
}
 
function npAsKindWhy(st, k) {
  const one = st && st.kinds && st.kinds[k];
  return String((one && one.why) || '').trim();
}
 
function npAsUseOf(col) {
  const u = String((col && col.use) || '');
  return u === 'on' || u === 'off' || u === 'ask' ? u : 'on';
}
function npAsOnCount(colId) {
  return (_npClipsCache || []).filter(c => c && c.col === colId).length;
}









const NP_STATS_KEY = 'note_stats';
async function npStatsReadAll() {
  try { const d = await chrome.storage.local.get(NP_STATS_KEY); return (d && d[NP_STATS_KEY]) || {}; }
  catch (_) { return {}; }
}
async function npStatsRead(noteId) {
  if (!noteId) return null;
  const all = await npStatsReadAll();
  return all[String(noteId)] || null;
}
async function npStatsWrite(noteId, stats) {
  const id = String(noteId || '').split('?')[0];
  if (!id || !stats) return { ok: false, error: 'noteId 或 stats 为空' };
  try {
    const all = await npStatsReadAll();
    all[id] = {
      likes: Number(stats.likes || 0) || 0,
      collects: Number(stats.collects || 0) || 0,
      comments: Number(stats.comments || 0) || 0,
      raw: String(stats.raw || ''),
      fetchedAt: Date.now(),
    };
    await chrome.storage.local.set({ [NP_STATS_KEY]: all });
    return { ok: true, id };
  } catch (e) { return { ok: false, error: String((e && e.message) || e) }; }
}

 
function npExploreIdByUrl(u) {
  if (!u) return '';
  const m = String(u).match(/\/explore\/([^?#]+)/);
  return m ? m[1].split('?')[0] : '';
}



async function npStatsWriteByTitle(list, noteStatsAll) {
  const hit = [];
  const miss = [];
  if (!Array.isArray(list)) list = [];
  if (!noteStatsAll || typeof noteStatsAll !== 'object') noteStatsAll = {};
  for (const n of list) {
    if (!n || n.status !== '已发') continue;
    const expId = npExploreIdByUrl(n.url);
    if (!expId) { miss.push({ id: n.id, reason: '档案没记 url' }); continue; }
    const s = noteStatsAll[expId];
    if (!s) { miss.push({ id: n.id, reason: '还没抓主页', expId }); continue; }
    n.stats = s;
    n.statsAt = s.fetchedAt;
    hit.push(n.id);
  }
  return { hit, miss };
}



const NP_STATS_FRESH_MS = 7 * 86400 * 1000;
async function npStatsAdopt() {
  const list = await npNotesAll();
  const stats = await npStatsReadAll();
  const { hit, miss } = await npStatsWriteByTitle(list, stats);
  if (hit.length) {
    await npNotesSync(async () => {
      try { await chrome.storage.local.set({ [NP_NOTES_KEY]: list }); } catch (_) {}
    });
  }
  const adopted = hit.length;
  const expired = list.filter(n => n && n.stats && n.stats.fetchedAt && (Date.now() - n.stats.fetchedAt > NP_STATS_FRESH_MS)).length;
  console.info('[stats-adopt] hit=' + adopted + ' miss=' + miss.length + ' expired=' + expired);
  return { hit: adopted, miss: miss.length, expired, sample: miss.slice(0, 5) };
}






const NP_DGENS_KEY = 'note_dgens';
const NP_ASMS_KEY = 'note_asms';
async function npDgensRead() { try { const d = await chrome.storage.local.get(NP_DGENS_KEY); return (d && d[NP_DGENS_KEY]) || {}; } catch (_) { return {}; } }
async function npAsmsRead()  { try { const d = await chrome.storage.local.get(NP_ASMS_KEY);  return (d && d[NP_ASMS_KEY])  || {}; } catch (_) { return {}; } }

async function npDgensUpdate(noteId, dgen) {
  const map = await npDgensRead();
  const flat = npDgenFlat(dgen);
  if (flat) map[String(noteId)] = { flat, at: Date.now() };
  else delete map[String(noteId)];
  try { await chrome.storage.local.set({ [NP_DGENS_KEY]: map }); } catch (_) {}
}
async function npAsmsUpdate(noteId, asm) {
  const map = await npAsmsRead();
  const flat = npAsmFlat(asm);
  if (flat) map[String(noteId)] = { flat, at: Date.now() };
  else delete map[String(noteId)];
  try { await chrome.storage.local.set({ [NP_ASMS_KEY]: map }); } catch (_) {}
}

 
function npDgenFlat(g) {
  if (!g || typeof g !== 'object') return '';
  const out = [];
  if (Array.isArray(g.points) && g.points.length) {
    out.push('重点：');
    for (const p of g.points) {
      if (!p) continue;
      const t = String(p.t || '').trim();
      if (!t) continue;
      const why = String(p.why || '').trim();
      out.push('  - ' + t + (why ? '（' + why + '）' : ''));
    }
  }
  const segs = Array.isArray(g.segs) ? g.segs : [];
  for (let i = 0; i < segs.length; i++) {
    const s = segs[i];
    if (!s) continue;
    const role = String(s.role || '').trim();
    const text = String(s.text || '').trim();
    const prompt = String(s.prompt || '').trim();
    if (!text && !role) continue;
    out.push('【' + (i + 1) + '】' + (role ? role + '：' : '') + text);
    if (prompt) out.push('  - ' + prompt);
  }
  return out.join('\n');
}

 
function npAsmFlat(a) {
  if (!a || typeof a !== 'object') return '';
  const out = [];
  const bgmId = String(a.bgmId || '').trim();
  if (bgmId) out.push('BGM: ' + bgmId);
  if (Array.isArray(a.sections)) {
    for (let i = 0; i < a.sections.length; i++) {
      const s = a.sections[i];
      if (!s) continue;
      const ck = String(s.cardKey || '').trim();
      if (!ck) continue;
      out.push('[' + (i + 1) + '] ' + ck);
      if (Array.isArray(s.scenes)) {
        for (const sc of s.scenes) {
          if (!sc) continue;
          const t = String(sc.text || '').trim();
          if (t) out.push('  - ' + t);
        }
      }
    }
  }
  return out.join('\n');
}

 
function npArchiveFlatSync(noteId, snap) {
  if (!noteId || !snap) return;
  Promise.resolve().then(async () => {
    try {
      if (snap.dgen && Array.isArray(snap.dgen.segs) && snap.dgen.segs.length) await npDgensUpdate(noteId, snap.dgen);
      else await npDgensUpdate(noteId, null);
      if (snap.asm) await npAsmsUpdate(noteId, snap.asm);
      else await npAsmsUpdate(noteId, null);
    } catch (_) {}
  });
}














async function npUsageByKbCat() {
  const map = new Map();
  const uncat = { catTitle: '默认', allItems: [], coveredIds: new Set(), blankIds: new Set(), pubNoteByKey: new Map() };
  map.set('默认', uncat);
  try {
    const r = await _diagSay('getKnowledgeBase');
    const entries = ((r && r.entries) || []).filter(e => e && e.isActive !== false);
    for (const e of entries) {
      const cat = String(e.category || e.cat || '默认').trim() || '默认';
      if (!map.has(cat)) map.set(cat, { catTitle: cat, allItems: [], coveredIds: new Set(), blankIds: new Set(), pubNoteByKey: new Map() });
      const t = String(e.title || '').trim();
      const id = String(e.id || '').trim();
      if (t || id) map.get(cat).allItems.push({ id, title: t });
    }
  } catch (_) {}
   
  try {
    const list = await npNotesAll();
    for (const n of list) {
      if (!n || !Array.isArray(n.kb)) continue;
      for (const k of n.kb) {
        const id = String((k && k.id) || '').trim();
        const ttl = String((k && k.title) || '').trim();
        if (!id && !ttl) continue;
        for (const c of map.values()) {
          
          const hit = c.allItems.find(it => (id && it.id === id) || (ttl && it.title === ttl));
          if (hit) {
            const key = hit.id || hit.title;
            c.coveredIds.add(key);
            
            if (n.status === '已发' || n.status === '已归档') {
              const landed = c.pubNoteByKey.get(key);
              if (!landed || (landed.status !== '已发' && n.status === '已发')) c.pubNoteByKey.set(key, n);
            }
          }
        }
      }
    }
  } catch (_) {}
  return map;
}




async function npAuditTopicsAlgo() {
  const map = await npUsageByKbCat();
  const statsAll = await npStatsReadAll();
  const statsFetched = Object.keys(statsAll).length > 0;
  const now = Date.now();
  const out = [];
  for (const c of map.values()) {
    const blank = c.allItems.filter(it => !c.coveredIds.has(it.id || it.title));
    const covered = c.allItems.filter(it => c.coveredIds.has(it.id || it.title));
    let conclusion;
    if (c.allItems.length === 0) conclusion = '空类';           
    else if (covered.length === 0) conclusion = '全空白';
    else if (blank.length === 0) conclusion = '全讲过';
    else conclusion = '有空白 + 有表现';
    
    const dayLikes = [];
    for (const n of c.pubNoteByKey.values()) {
      const expId = npExploreIdByUrl(n.url || '');
      const stats = expId ? statsAll[expId] : null;
      if (!stats || !(stats.likes || stats.collects || stats.comments)) continue;
      const sentAt = (n.statusAt && n.statusAt['已发']) || n.updatedAt || 0;
      if (!sentAt) continue;
      dayLikes.push((stats.likes || 0) / Math.max(1, Math.floor((now - sentAt) / 86400e3)));
    }
    out.push({
      catTitle: c.catTitle,
      total: c.allItems.length,
      covered: covered.length,
      blank: blank.length,
      conclusion,
      blankIds: blank,
      coveredIds: covered,
      pub: c.pubNoteByKey.size,
      avgDay: dayLikes.length ? dayLikes.reduce((a, b) => a + b, 0) / dayLikes.length : null,
    });
  }
  
  const order = { '全空白': 0, '有空白 + 有表现': 1, '全讲过': 2, '空类': 3 };
  out.sort((a, b) => (order[a.conclusion] - order[b.conclusion]) || a.catTitle.localeCompare(b.catTitle, 'zh-Hans-CN'));
  out.statsFetched = statsFetched;
  return out;
}

 
async function npAuditSentAlgo() {
  const all = await npNotesAll();
  const statsAll = await npStatsReadAll();
  const sent = all.filter(n => n && n.status === '已发');
  const rows = sent.map(n => {
    const m = (n.url || '').match(/\/explore\/([^?#]+)/);
    const expId = m ? m[1] : '';
    const stats = expId ? statsAll[expId] : null;
    return {
      id: n.id,
      title: n.title || '',
      url: n.url || '',
      expId,
      stats,
      hasStats: !!(stats && (stats.likes || stats.collects || stats.comments)),
      fetchedAt: n.statsAt || (stats && stats.fetchedAt) || 0,
      dir: n.dir,
      kOut: n.kOut,
      dOut: n.dOut,
      sentAt: (n.statusAt && n.statusAt['已发']) || n.updatedAt || 0,
    };
  }).sort((a, b) => b.sentAt - a.sentAt);
  return {
    total: sent.length,
    withStats: rows.filter(r => r.hasStats).length,
    rows,
  };
}

let _npRvDelegated = false;
 
function ensureNpRvDelegation() {
  if (_npRvDelegated) return;
  const root = document.getElementById('noteReviewContent');
  if (!root) return;
  _npRvDelegated = true;
  root.addEventListener('click', async function (ev) {
    const t = ev.target;
    if (!t || !t.closest) return;
     
    if (t.closest('.npar-pw-back')) { _npArPlayView = null; npAuditPlayPaint(); return; }
    const pwBecome = t.closest('.npar-pw-become');
    if (pwBecome) {
      const nm = String(pwBecome.getAttribute('data-pw-become') || '');
      if (!nm) return;
      await npCurPlaySet(nm);
      _npArPlayView = null;
      toast('本轮改钉「' + nm + '」了——它以前发过的账还在，连发从今天这篇算起；下一篇文章照这一招写');
      npAuditPlayPaint();
      return;
    }
    const pwAgain = t.closest('.npar-pw-again');
    if (pwAgain) {
      const nm = String(pwAgain.getAttribute('data-pw-again') || '');
      const sk = npPlaySkeleton(nm);
      if (!nm || !sk) return;
      await npPwCreate(nm, sk.out === 'long' ? 'long' : 'img');   
      return;
    }
    if (t.closest('.npar-pw-swap')) { _npArPlayView = null; await npPwOpen('swap'); return; }
    if (t.closest('.npar-pw-ai')) { _npArPlayView = null; await npPwOpen('new', 'in'); await npPwAiAdd(); return; }
    const pwStop = t.closest('.npar-pw-stop');
    if (pwStop) {
      const nm = String(pwStop.getAttribute('data-pw-stop') || '');
      if (!nm) return;
      await npPlayStop(nm, '你在复盘「🎭 玩法效果」上标的：这一阵不用了');
      _npArPlayView = null;
      toast('「' + nm + '」进停用了（留底，这条横幅上「🔁 换个玩法」进去、点「停用」那一签再点一下能复活）');
      npAuditPlayPaint();
      return;
    }
     
    const fn = t.closest('.npar-fnew');
    if (fn) { await npFacadeCreate(fn.getAttribute('data-fk') || ''); return; }
    const fo = t.closest('.npar-fopen');
    if (fo) { const n = await npArFindById(fo.getAttribute('data-id') || ''); if (n) npDirGo(n); return; }
    if (t.closest('.npar-frefresh')) { await npFacadeRefresh(t.closest('.npar-frefresh').getAttribute('data-id') || ''); return; }
    if (t.closest('.npar-fpin')) { await npFacadePinOpen(t.closest('.npar-fpin').getAttribute('data-id') || ''); return; }
  });
}

 
function npAuditGo(which) {
  ensureNpRvDelegation();
  document.querySelectorAll('.audit-tab').forEach(x => x.classList.toggle('active', x.getAttribute('data-atab') === which));
  const tp = document.getElementById('auditTopicsPane');
  const sp = document.getElementById('auditSentPane');
  const pp = document.getElementById('auditPlayPane');
  if (tp) tp.style.display = (which === 'topics' ? '' : 'none');
  if (sp) sp.style.display = (which === 'sent' ? '' : 'none');
  if (pp) pp.style.display = (which === 'play' ? '' : 'none');
  if (which === 'topics') npAuditTopicsPaint();
  else if (which === 'play') npAuditPlayPaint();
  else npAuditSentPaint();
}







 
async function npAuditPlayAlgo() {
  const all = await npNotesAll();
  const statsAll = await npStatsReadAll();
  const now = Date.now();
  const sent = all.filter(n => n && n.status === '已发');
  const withStat = (n) => {
    const m = (n.url || '').match(/\/explore\/([^?#]+)/);
    const st = m ? statsAll[m[1]] : null;
    return (st && (st.likes || st.collects || st.comments)) ? st : null;
  };
  const sentTimes = sent.map(n => (n.statusAt && n.statusAt['已发']) || n.updatedAt || 0);
  const alive = sent.map((n, i) => ({ n: n, st: withStat(n), at: sentTimes[i] })).filter(x => x.st);
  const accC = alive.length ? alive.reduce((t, x) => t + (Number(x.st.comments) || 0), 0) / alive.length : null;
  const accL = alive.length ? alive.reduce((t, x) => t + (Number(x.st.likes) || 0), 0) / alive.length : null;
  const fetchedAt = alive.reduce((t, x) => Math.max(t, Number(x.st.fetchedAt) || 0), 0);
  const byPlay = {};
  const playOf = (n) => npNotePlayOf(n);
  alive.forEach(x => {
    const play = playOf(x.n);
    if (play) (byPlay[play] = byPlay[play] || []).push(x);
  });
  
  const allByPlay = {};
  sent.forEach(n => { const play = playOf(n); if (play) (allByPlay[play] = allByPlay[play] || []).push(n); });
  const sentAtOf = (n) => (n.statusAt && n.statusAt['已发']) || n.updatedAt || 0;
  const rows = (await npPlayLedgerNames()).map(nm => {
    const p = npPlaySkeleton(nm) || { name: nm, grp: '' };
    const arr = byPlay[p.name] || [];
    const all = allByPlay[p.name] || [];
    if (!all.length) return { name: p.name, grp: p.grp, n: 0, nSent: 0 };
    if (!arr.length) return { name: p.name, grp: p.grp, n: 0, nSent: all.length, lastAt: Math.max.apply(null, all.map(sentAtOf)) };
    const avgC = arr.reduce((t, x) => t + (Number(x.st.comments) || 0), 0) / arr.length;
    const avgL = arr.reduce((t, x) => t + (Number(x.st.likes) || 0), 0) / arr.length;
    const days = Math.max(...arr.map(x => Math.max(1, Math.floor((now - x.at) / 86400e3))));
    const topX = arr.reduce((a, b) => ((Number(b.st.comments) || 0) > (Number(a.st.comments) || 0) ? b : a), arr[0]);
    return {
      name: p.name, grp: p.grp, n: arr.length, nSent: all.length, avgC: avgC, avgL: avgL, days: days,
      ratio: accC ? avgC / accC : null,
      topC: Number((topX && topX.st && topX.st.comments) || 0) || 0,
      topTitle: String((topX && topX.n && (topX.n.title || (topX.n.draft || '').split('\n')[0])) || '').trim().slice(0, 30),
      lastAt: Math.max.apply(null, all.map(sentAtOf)),
    };
  });
  
  rows.sort((a, b) => (b.n ? 1 : 0) - (a.n ? 1 : 0) || (b.n - a.n) || (b.nSent - a.nSent) || String(a.name).localeCompare(String(b.name), 'zh'));
  return { rows: rows, accC: accC, accL: accL, nAll: alive.length, fetchedAt: fetchedAt };
}
const plFmt = v => { const x = Math.round(Number(v) * 10) / 10; return Number.isInteger(x) ? String(x) : x.toFixed(1); };

async function npAuditPlayPaint() {
  const pane = document.getElementById('auditPlayPane');
  if (!pane) return;
  pane.innerHTML = '<div class="audit-loading">🎭 玩法效果在算——按玩法标归堆，只摆数…</div>';
  let pl, st;
  try { pl = await npAuditPlayAlgo(); st = await npPlayStateRead(); }
  catch (e) { pane.innerHTML = '❌ 出错了：' + esc(String((e && e.message) || e)); return; }
  const sb = { by: {}, accC: pl.accC };                 
  pl.rows.forEach(r => { if (r && r.name) sb.by[r.name] = r; });
  const bar = npArPlayBarHtml(st, sb, _npArPlayView);
  const rows = pl.rows.filter(r => r.nSent);            
  const stoppedSet = new Set(((st && st.stop) || []).map(x => x && x.name).filter(Boolean));
  const curName = (st && st.cur && st.cur.name) || '';
  const chip = (txt, fg, bg, bd) => '<span style="font-size:10px;font-weight:700;color:' + fg + ';background:' + bg + ';border:1px solid ' + bd + ';border-radius:8px;padding:0 7px;">' + txt + '</span>';
  const head = '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:9px;">' +
    '<span class="note-xs">📕 就着「已发复盘」那份抓主页快照现算' + (pl.fetchedAt ? '（' + npArAgo(pl.fetchedAt) + '抓的）' : '') + ' · 主页上手发的没玩法标、不进账</span>' +
    '<span style="flex:1;"></span></div>';
  const emptyBox = (txt) => '<div style="max-width:720px;"><div class="card card-pad"><div class="audit-hd">玩法效果 —— 每一招发过几篇、数怎么样</div>' + head +
    '<div class="audit-empty">' + txt + '</div>' +
    '<div class="note-xs" style="margin-top:10px;">📌 这一页<b>只摆数、不替你下结论</b>——哪招接着发、哪招停一停，在上面那条「🎭 本轮玩法」上动手（📤 再发一篇 / 🔁 换玩法 / 📈 加频次 / ⏸ 停用都在那儿）。</div>' +
    '</div></div>';
  if (!pl.nAll) { pane.innerHTML = '<div style="max-width:720px;">' + bar + emptyBox('还没抓过主页的数——先去「📈 已发复盘」页抓一次（点赞 / 收藏 / 评论都是抓主页时顺带读的），这页才算得出账。') + '</div>'; return; }
  if (!rows.length) { pane.innerHTML = '<div style="max-width:720px;">' + bar + emptyBox('还没有带玩法标的已发篇——「📒 笔记档案 → ✍️ 新建笔记」点 🔥 引流 那一格起一篇，写稿那一屏顶上点一招（或上面那条点「🎭 去挑一招」），发出去两天后这页就有它的账。') + '</div>'; return; }
  const accLine = '账号平均：就着 <b>' + pl.nAll + '</b> 篇已发（玩法篇 + 平常篇一起算）· 平均 <b style="color:#1f2329;">💬' + plFmt(pl.accC) + ' 评</b> / 👍' + Math.round(pl.accL) + ' 赞 —— 下面每一招的倍数都是对着这条线算的，用哪招你自己拿主意。';
  const rowsHtml = rows.map(r => {
    const line1 = r.n
      ? '有数的 <b>' + r.n + '</b> 篇（已发 ' + r.nSent + ' 篇）· 跑了 <b>' + r.days + '</b> 天 · 平均 <b style="color:#1f2329;">💬' + plFmt(r.avgC) + ' 评</b> / 👍' + Math.round(r.avgL) + ' 赞' +
        (r.ratio != null ? '　· 是账号平均的 <b style="color:#1f2329;">' + r.ratio.toFixed(2) + ' 倍</b>' : '')
      : '已发 <b>' + r.nSent + '</b> 篇 · <span style="color:#8a929e;">评论数还没回填（发出去两天后自动补）</span>';
    return '<div style="border:1px solid var(--line);border-radius:10px;background:#fff;padding:9px 12px;margin-bottom:8px;' + (stoppedSet.has(r.name) ? 'opacity:.62;' : '') + '">' +
      '<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">' +
        '<b style="font-size:12.5px;color:#1f2329;">🎭 ' + esc(r.name) + '</b>' +
        (r.name === curName ? chip('本轮在用', '#0a7b5a', '#eaf7f0', '#c9e9d8') : '') +
        (stoppedSet.has(r.name) ? chip('⏸ 已停用', '#8a929e', '#f5f6f8', '#e5e8ee') : '') +
        (r.grp ? chip(esc(r.grp), '#616b78', '#f5f6f8', '#e5e8ee') : '') +
        '<span style="flex:1;"></span><span style="font-size:10.5px;color:#8a929e;">最近一次 ' + (npArAgo(r.lastAt) || '—') + '</span>' +
      '</div>' +
      '<div style="font-size:11px;color:#4b5563;margin-top:5px;line-height:1.8;">' + line1 + '</div>' +
      (r.topC ? '<div style="font-size:11px;color:#4b5563;line-height:1.8;">最高的一篇：💬' + r.topC + ' 评 · 《' + esc(r.topTitle || '') + '》</div>' : '') +
    '</div>';
  }).join('');
  pane.innerHTML = '<div style="max-width:720px;">' +
    bar +
    '<div class="card card-pad">' +
      '<div class="audit-hd">玩法效果 —— 每一招发过几篇、数怎么样（只摆数，结论你自己下）</div>' + head +
      '<div style="border:1px solid var(--line);border-radius:9px;background:#fafbfc;padding:8px 11px;margin-bottom:10px;font-size:11.5px;color:#4b5563;line-height:1.8;">' + accLine + '</div>' +
      rowsHtml +
      '<div class="note-xs" style="margin-top:10px;">📌 玩法标是建篇那一刻自动记的，不用手标；主指标看「💬 评论」——玩法戏都在评论区。' +
        '要换招 / 停用 / 加频次：上面那条「🎭 本轮玩法」上动手，这一页不代你做决定。</div>' +
    '</div></div>';
}

 

async function npAuditTopicsPaint() {
  const pane = document.getElementById('auditTopicsPane');
  if (!pane) return;
  pane.innerHTML = '<div class="audit-loading">📋 选题盘点在算，按知识库类看「讲过 / 没讲过」…</div>';
  try {
    const r = await Promise.all([npAuditTopicsAlgo(), npNotesAll()]);
    const cls = r[0], list = r[1] || [];
    pane.innerHTML = npFacadeBar(list) + npAuditTopicsHtml(cls, cls.statsFetched);
    pane.querySelectorAll('tr[data-cat]').forEach(tr => {
      tr.addEventListener('click', () => npAuditOpenCat(tr.getAttribute('data-cat')));
    });
    pane.querySelectorAll('.audit-blank-item').forEach(el => {
      el.addEventListener('click', (ev) => {
        ev.stopPropagation();
        const ttl = el.getAttribute('data-title') || '';
        if (!ttl) return;
        npAuditOpenCat(el.getAttribute('data-cat') || '默认', ttl);
      });
    });
  } catch (e) { pane.innerHTML = '❌ 出错了：' + esc(String(e && e.message || e)); }
}

function npAuditTopicsHtml(cls, statsFetched) {
  if (!cls.length) return '<div class="audit-empty">还没在「账号规划 → 知识库」录入条目。先去录入，再回来看盘点。</div>';
  const visible = cls.filter(c => c.conclusion !== '空类');
  if (!visible.length) return '<div class="audit-empty">知识库当前没有可盘点的条目。</div>';
  
  const defRow = visible.find(c => c.catTitle === '默认');
  const defCount = defRow ? defRow.total : 0;
  const parts = [];
  if (defCount > 0) {
    parts.push('<div class="audit-hint" style="background:#fff7e6;border:1px solid #f0dcb0;border-radius:6px;padding:8px 10px;margin-bottom:10px;">⚠ 还有 <b>' + defCount + '</b> 条归在「默认」类（多半是老档没归类）。点 <b>账号规划 → 知识库</b>，点 <b>🤖 AI 批量归类</b> 一键归到 8 类。</div>');
  }
  parts.push('<table class="audit-tbl">');
  parts.push('<colgroup><col><col style="width:80px;"><col style="width:80px;"><col style="width:200px;"><col style="width:170px;"></colgroup>');
  parts.push('<thead><tr><th>知识库类</th><th>总条目</th><th>还差</th><th>结论 · 行末查</th><th title="已发几篇 + 这类已发笔记的日均赞（点赞 ÷ 发布天数，抓主页顺带读的）">表现</th></tr></thead><tbody>');
  for (const c of visible) {
    
    let chip, chipCls, tip;
    if (c.catTitle === '默认') {
      chip = '🟧 待归类';
      chipCls = 'mix';
      tip = '这一类大多是老档没归类——点「账号规划 → 知识库」用 🤖 AI 批量归类一键处理';
    } else if (c.conclusion === '全空白') {
      chip = '🟥 全空白';
      chipCls = 'bad';
      tip = '这一类里所有条目都没写过 —— 有料没用上，挑几条加进下次规划';
    } else if (c.conclusion === '全讲过') {
      chip = '🟩 全讲过';
      chipCls = 'ok';
      tip = '这一类里所有条目都写过 —— 可以换个角度写、或者先停一停';
    } else {
      chip = '🟨 有空白 + 有表现';
      chipCls = 'mix';
      tip = '部分讲过 —— 「还差」列里点进去看具体哪些没写';
    }
    parts.push('<tr data-cat="' + esc(c.catTitle) + '" title="' + esc(tip) + '">');
    parts.push('<td><strong>' + esc(c.catTitle) + '</strong>' + (c.catTitle === '默认' ? ' <span style="color:#b45309;font-size:10px;">⚠ 待归类</span>' : '') + '</td>');
    parts.push('<td>' + c.total + '</td>');
    parts.push('<td style="color:' + (c.blank > 0 ? '#c0392b' : '#8a929e') + ';">' + c.blank + '</td>');
    parts.push('<td><span class="audit-chip audit-chip-' + chipCls + '">' + chip + '</span></td>');
    
    let perf;
    if (!c.pub) perf = '还没发过';
    else if (statsFetched === false) perf = '<span style="color:#b6bec9;" title="点赞是抓主页顺带读的——先抓一次才有">—</span>';
    else if (c.avgDay == null) perf = '已发 ' + c.pub + ' 篇 · 表现还没读到';
    else perf = '已发 <b>' + c.pub + '</b> 篇 · 日均赞 <b>≈' + (Number.isInteger(c.avgDay) ? String(c.avgDay) : c.avgDay.toFixed(1)) + '</b>';
    parts.push('<td style="text-align:right;white-space:nowrap;">' + perf + '</td>');
    parts.push('</tr>');
    if (c.conclusion === '有空白 + 有表现' && c.blankIds.length) {
      parts.push('<tr data-cat="' + esc(c.catTitle) + '"><td colspan="5" class="audit-tbl-sub"><b>还没写过：</b>');
      c.blankIds.slice(0, 8).forEach(it => {
        parts.push('<span class="audit-blank-item" data-cat="' + esc(c.catTitle) + '" data-title="' + esc(it.title) + '">' + esc(it.title) + '</span> ');
      });
      if (c.blankIds.length > 8) parts.push('… 等 ' + c.blankIds.length + ' 条');
      parts.push('</td></tr>');
    }
  }
  parts.push('</tbody></table>');
  parts.push('<div class="audit-hint">点行／点条目 → 这一类的清单列出来；勾上挑一篇发笔记用。</div>');
  return parts.join('');
}

let _npAuditPick = new Set();   
function _npAuditPickPaint(m) {
  const btn = m.querySelector('.audit-plan-push');
  if (!btn) return;
  const n = _npAuditPick.size;
  btn.disabled = !n;
  btn.textContent = '📅 排进本周计划' + (n ? '（已勾 ' + n + ' 条）' : '');
  btn.title = n ? '把勾上的条目写进「排产表」本周' : '先勾几条第「没写过」的条目';
}

async function npAuditOpenCat(cat, focusTitle) {
  try {
    const list = await npNotesAll();
    const hit = list.filter(n => Array.isArray(n.kb) && n.kb.some(k => {
      const t = String((k && (k.title || k.id)) || '').trim();
      return !!t;       
    }));
    const map = await npUsageByKbCat();
    const c = map.get(cat) || { allItems: [], coveredIds: new Set() };
    
    const coveredSet = new Set();
    hit.forEach(n => {
      if (!Array.isArray(n.kb)) return;
      n.kb.forEach(k => {
        const id = String((k && k.id) || '').trim();
        const ttl = String((k && k.title) || '').trim();
        if (c.allItems.some(it => (id && it.id === id) || (ttl && it.title === ttl))) {
          coveredSet.add(n.id);
        }
      });
    });
    const notes = list.filter(n => coveredSet.has(n.id));
    const blank = c.allItems.filter(it => !c.coveredIds.has(it.id || it.title));
     
    const pickNotes = list.filter(n => n && (n.status === '草稿' || n.status === '代发'))
      .sort((a, b) => String(a.title || '').localeCompare(String(b.title || ''), 'zh-Hans-CN'));
     
    const plannedByTitle = new Map();
    try {
      const d = await chrome.storage.local.get('note_plan');
      const its = (d && d.note_plan && Array.isArray(d.note_plan.items)) ? d.note_plan.items : [];
      its.forEach(it => { if (it && it.title) plannedByTitle.set(String(it.title), it); });
    } catch (_) {}
    _npAuditPick.clear();
    const html = [
      '<div>',
      '<h3>' + esc(cat) + '</h3>',
      '<h4>已写过（' + notes.length + ' 篇）：</h4>',
    ];
    if (!notes.length) html.push('<p class="audit-empty">这一类还没写过。</p>');
    else {
      html.push('<ul>');
      notes.forEach(n => {
        html.push('<li><a href="#" data-nid="' + esc(n.id) + '">' + esc(n.title || '（无标题）') + '</a> · ' + esc(n.status || '') + '</li>');
      });
      html.push('</ul>');
    }
    html.push('<h4>还没写过（' + blank.length + ' 条）：</h4>');
    if (!blank.length) html.push('<p class="audit-empty">全讲过了。</p>');
    else {
      html.push('<ul class="audit-blank-list">');
      blank.forEach(it => {
        const hi = focusTitle && it.title === focusTitle ? ' style="background:#fff7e6;"' : '';
        const catAttr = esc(cat);
        const idAttr = esc(it.id || '');
        const titleAttr = escAttr(it.title || '');
        const idHtml = it.id ? ' <small>(' + esc(it.id) + ')</small>' : '';
        const planned = plannedByTitle.get(String(it.title || ''));
        const addBtn = '<button type="button" class="audit-blank-add" data-kbid="' + idAttr + '" data-kbtitle="' + titleAttr + '" data-cat="' + catAttr + '">➕ 加进下次规划</button>';
        if (planned) {
          const dn = planned.day ? NotePlan.columnDayName(planned.day) : '';
          html.push('<li' + hi + '>' +
            '<span class="audit-blank-title">' + esc(it.title) + idHtml + '</span>' +
            '<span class="audit-planned-badge">📅 已排 ' + esc(dn || '本周') + '</span>' +
            addBtn +
            '</li>');
        } else {
          html.push('<li' + hi + '>' +
            '<label class="audit-pick-label"><input type="checkbox" class="audit-pick" data-pkey="' + titleAttr + '">' +
            '<span class="audit-blank-title">' + esc(it.title) + idHtml + '</span></label>' +
            addBtn +
            '</li>');
        }
      });
      html.push('</ul>');
      html.push('<div id="auditCatPicker" class="audit-cat-picker" hidden></div>');
      html.push('<div class="audit-plan-bar">' +
        '<button type="button" class="audit-plan-push" disabled title="先勾几条第「没写过」的条目">📅 排进本周计划</button>' +
        '<span class="audit-plan-tip">勾「没写过」的条目 → 点这颗钮＝写进「排产表」本周；写稿到「① 挑知识」这一步，顶上的「📚 按规划发」卡会把它摆出来。</span>' +
        '</div>');
    }
    html.push('<div class="audit-hint" style="margin-top:14px;">点外面或这篇标题 → 跳回笔记档案</div>');
    html.push('</div>');
    const m = document.createElement('div');
    m.className = 'audit-modal';
    m.dataset.cat = cat;
    m.innerHTML = html.join('');
    document.body.appendChild(m);
     
    m.addEventListener('change', (ev) => {
      const cb = ev.target.closest('.audit-pick');
      if (!cb) return;
      const key = String(cb.getAttribute('data-pkey') || '');
      if (!key) return;
      if (cb.checked) _npAuditPick.add(key); else _npAuditPick.delete(key);
      _npAuditPickPaint(m);
    });
    m.addEventListener('click', async (ev) => {
       
      const pushBtn = ev.target.closest('.audit-plan-push');
      if (pushBtn) {
        ev.preventDefault();
        ev.stopPropagation();
        const added = await npAuditPlanPush();
        if (added) { m.remove(); npAuditOpenCat(cat); }
        return;
      }
       
      const addBtn = ev.target.closest('.audit-blank-add');
      if (addBtn) {
        ev.preventDefault();
        ev.stopPropagation();
        const picker = m.querySelector('#auditCatPicker');
        if (!picker) return;
        const kbId = addBtn.getAttribute('data-kbid');
        const kbTitle = addBtn.getAttribute('data-kbtitle');
        const kbCat = addBtn.getAttribute('data-cat');
        if (!kbId) { _diagKbMessage ? null : null; return; }
        if (!pickNotes.length) {
          picker.innerHTML = '<div class="audit-picker-empty">还没有草稿/代发的档案可挑——先去「发笔记 → 档案」建一篇草稿。</div>';
          picker.hidden = false;
          return;
        }
        picker.innerHTML = '<div class="audit-picker-hint">➕ 把『<b>' + esc(kbTitle || kbId) + '</b>』挂到哪一篇档案的「知识库引用」？</div>' +
          '<div class="audit-picker-chips">' +
          pickNotes.map(n => '<button type="button" class="audit-picker-chip" data-picknid="' + esc(n.id) + '">' + esc(n.title || '（无标题）') + ' <small>· ' + esc(n.status || '') + '</small></button>').join('') +
          '</div>' +
          '<button type="button" class="audit-picker-cancel">取消</button>';
        picker.hidden = false;
        picker.querySelector('.audit-picker-cancel').onclick = function () { picker.hidden = true; picker.innerHTML = ''; };
        picker.querySelectorAll('.audit-picker-chip').forEach(chip => {
          chip.onclick = async () => {
            const nid = chip.getAttribute('data-picknid');
            const r = await npNoteAddKb(nid, { id: kbId, title: kbTitle, cat: kbCat });
            if (r && r.ok) {
              picker.innerHTML = '<div class="audit-picker-ok">✅ 已挂到「' + esc((list.find(x => x.id === nid) || {}).title || nid) + '」' + (r.added ? '' : '（这条知识之前已挂过，不重复加）') + '</div>';
              setTimeout(() => { npAuditOpenCat(cat, kbTitle); m.remove(); }, 900);
            } else {
              picker.innerHTML = '<div class="audit-picker-empty">❌ 注入失败：' + esc((r && r.why) || '未知错误') + '</div>';
            }
          };
        });
        return;
      }
      const t = ev.target.closest('[data-nid]');
      if (t) {
        ev.preventDefault();
        m.remove();
        switchMainTab('noteArchive');
        window._npArchiveFocus = t.getAttribute('data-nid');
      } else if (ev.target === m) {
        m.remove();
      }
    });
  } catch (e) {
    console.error('[audit-open-cat]', e);
  }
}





async function npAuditPlanPush() {
  const titles = [..._npAuditPick];
  if (!titles.length) return 0;
  try {
    const g = await npPlanGridRead();
    const days = NP_WEEK_DAYS.filter(d => NP_PLAN_PLATS.some(p => String(((g[d] || {})[p.id]) || '').indexOf('知识') >= 0));
    const pool = days.length ? days : ['mon'];
    const d = await chrome.storage.local.get('note_plan');
    const plan = (d && d.note_plan && typeof d.note_plan === 'object') ? d.note_plan : {};
    if (!Array.isArray(plan.items)) plan.items = [];
    const existing = new Set(plan.items.map(it => String((it && it.title) || '')));
    let maxNo = 0;
    plan.items.forEach(it => { const n = Number(it && it.no); if (isFinite(n) && n > maxNo) maxNo = n; });
    let added = 0;
    for (const t of titles) {
      if (existing.has(t)) continue;
      plan.items.push({
        no: ++maxNo, title: t, type: 'howto',
        day: NP_WEEK_DAYS.indexOf(pool[plan.items.length % pool.length]) + 1,
        done: false,
      });
      existing.add(t);
      added++;
    }
    if (!added) return 0;
    await chrome.storage.local.set({ note_plan: plan });
    if (_npPlanCache) _npPlanCache = plan;   
    _npAuditPick.clear();
    toast('已把 ' + added + ' 条排进本周计划——写回排产表了');
    return added;
  } catch (e) {
    toast('排进计划失败：' + String((e && e.message) || e), 'error');
    return 0;
  }
}

async function npAuditSentPaint() {
  const pane = document.getElementById('auditSentPane');
  if (!pane) return;
  pane.innerHTML = '<div class="audit-loading">📈 已发复盘在算…</div>';
  try {
    const data = await npAuditSentAlgo();
    pane.innerHTML = npAuditSentHtml(data);
    const btnAll = pane.querySelector('#btnStatsRefetch');
    const btnOne = pane.querySelector('#btnStatsRefetchOne');
    if (btnAll) btnAll.addEventListener('click', npStatsRefetchAll);
    if (btnOne) btnOne.addEventListener('click', npStatsRefetchOne);
    pane.querySelectorAll('tr[data-nid]').forEach(tr => {
      const id = tr.getAttribute('data-nid');
      const url = tr.getAttribute('data-url');
      const title = tr.getAttribute('data-title') || '';
      tr.querySelector('.btn-open-note')?.addEventListener('click', (ev) => {
        ev.stopPropagation();
        if (url) chrome.tabs.create({ url });
      });
      tr.querySelector('.btn-stats-one')?.addEventListener('click', async (ev) => {
        ev.stopPropagation();
        if (!id) return;
        window._npCurReviewNote = { id, url, title };
        try { await npStatsRefetchOne(); } catch (e) { console.error('[refetch-one]', e); }
        npAuditSentPaint();
      });
      tr.addEventListener('click', () => {
        window._npCurReviewNote = { id, url, title };
        pane.querySelectorAll('tr[data-nid]').forEach(x => x.classList.toggle('active', x === tr));
        if (btnOne) btnOne.disabled = false;
      });
    });
  } catch (e) { pane.innerHTML = '❌ 出错了：' + esc(String(e && e.message || e)); }
}

function npAuditSentHtml(data) {
  if (!data.total) {
    return '<div class="audit-empty">还没有「已发」状态的档案可看 —— 先发表几篇，回这里看抓主页的数字趋势。</div>';
  }
  const pct = Math.round((data.withStats / data.total) * 100);
  const parts = [];
  parts.push('<div class="audit-stats-top">');
  parts.push('<span class="chip">已发 ' + data.total + ' 篇 · 抓到 ' + data.withStats + ' 篇（' + pct + '%）</span>');
  parts.push('<button id="btnStatsRefetch" class="n-btn">🔄 重抓全部已发主页</button>');
  parts.push('<button id="btnStatsRefetchOne" class="n-btn" disabled>🔄 重抓这一篇（先点行）</button>');
  parts.push('</div>');
  parts.push('<table class="audit-sent-tbl">');
  parts.push('<colgroup><col><col style="width:150px;"><col style="width:80px;"><col style="width:80px;"><col style="width:80px;"><col style="width:180px;"></colgroup>');
  parts.push('<thead><tr><th>标题（点行选中）</th><th>发表日 · 已发天数</th><th>🖊 点赞</th><th>⭐ 收藏</th><th>💬 评论</th><th>抓主页 · 操作</th></tr></thead><tbody>');
  for (const r of data.rows) {
    const age = r.sentAt ? Math.floor((Date.now() - r.sentAt) / 86400e3) + ' 天' : '—';
    const sentDate = r.sentAt ? new Date(r.sentAt).toLocaleDateString() : '—';
    const likes = r.hasStats ? formatNum(r.stats.likes) : '⚪';
    const collects = r.hasStats ? formatNum(r.stats.collects) : '—';
    const comments = r.hasStats ? formatNum(r.stats.comments) : '—';
    const fetchedLabel = r.fetchedAt ? new Date(r.fetchedAt).toLocaleString() : '⚪ 还没抓';
    const expired = r.fetchedAt && (Date.now() - r.fetchedAt > NP_STATS_FRESH_MS);
    const fetchedColor = expired ? '#b45309' : '#2e7d32';
    const fetchedBg = expired ? '#fff7e6' : 'transparent';
    parts.push('<tr data-nid="' + esc(r.id) + '" data-url="' + esc(r.url) + '" data-title="' + esc(r.title) + '">');
    parts.push('<td><button class="btn-open-note" type="button">' + esc(r.title || '（无标题）') + '</button></td>');
    parts.push('<td>' + sentDate + ' · ' + age + '</td>');
    parts.push('<td>' + likes + '</td><td>' + collects + '</td><td>' + comments + '</td>');
    parts.push('<td><span class="audit-fetched-tip" style="color:' + fetchedColor + ';background:' + fetchedBg + ';padding:1px 4px;border-radius:4px;" title="' + esc(r.url) + '">' + fetchedLabel + '</span> <button class="btn-stats-one n-btn-sm" type="button">🔄</button></td>');
    parts.push('</tr>');
  }
  parts.push('</tbody></table>');
  parts.push('<div class="audit-hint">💡 单行点中后，「🔄 重抓这一篇」按钮就生效；批量重抓走「🔄 重抓全部」。</div>');
  return parts.join('');
}

function formatNum(n) {
  n = Number(n || 0);
  if (!n) return '0';
  if (n < 1000) return String(n);
  if (n < 10000) return (n / 1000).toFixed(1) + 'k';
  return (n / 10000).toFixed(1) + '万';
}

 
window._npAuditCheck = async function () {
  const t = await npAuditTopicsAlgo();
  const s = await npAuditSentAlgo();
  const out = {
    topics: {
      totalCategories: t.length,
      fullBlank: t.filter(x => x.conclusion === '全空白').length,
      fullCovered: t.filter(x => x.conclusion === '全讲过').length,
      mix: t.filter(x => x.conclusion === '有空白 + 有表现').length,
      empty: t.filter(x => x.conclusion === '空类').length,
    },
    sent: { total: s.total, withStats: s.withStats },
  };
  console.info('[audit-check]', out);
  return out;
};







window._npPatchesCheck = async function () {
  const out = {};
  try { out.planned = (await npNotesAll()).filter(n => n && n.planDate).length; } catch (_) { out.planned = -1; }
  try { out.collections = (await npCollectionsRead()).length; } catch (_) { out.collections = -1; }
  try { out.clips = (await npClipsRead()).length; } catch (_) { out.clips = -1; }
  try { const d = await chrome.storage.local.get(NP_STATS_KEY); out.stats = Object.keys(d[NP_STATS_KEY] || {}).length; } catch (_) { out.stats = -1; }
  try { out.dgens = Object.keys(await npDgensRead()).length; } catch (_) { out.dgens = -1; }
  try { out.asms = Object.keys(await npAsmsRead()).length; } catch (_) { out.asms = -1; }
  
  try {
    const list = await npNotesAll();
    const svMap = {};
    list.forEach(n => { const k = '_sv:' + (n && n._sv != null ? n._sv : 'undef'); svMap[k] = (svMap[k] || 0) + 1; });
    out.notesTotal = list.length;
    out.notesSv = svMap;
  } catch (_) { out.notesTotal = -1; out.notesSv = {}; }
  console.info('[patches-check] A2~A6 索引:', out);
  return out;
};




function npLookShape(raw) {
  const o = (raw && typeof raw === 'object') ? raw : {};
  const out = {};
  NP_LOOK_AXES.forEach(a => {
    if (a.k === 'mark') return;                                
    const v0 = String(o[a.k] || '').trim();
    const v = a.k === 'born' ? (NP_BORN_ALIAS[v0] || v0) : (a.k === 'theme' ? (NP_THEME_ALIAS[v0] || v0) : v0);
    if (a.opts.indexOf(v) >= 0) out[a.k] = v;
  });
  const cap = VisualMotif.captionOf(o.cap);
  if (cap) out.cap = cap;
  let motif = String(o.motif || '').trim().slice(0, 16);   
  if (motif === '真人工作场景') motif = '人物工作场景';       
  if (motif) out.motif = motif;
  const casting = String(o.casting || '').trim().slice(0, 120);   
  if (casting) out.casting = casting;
  const layout = String(o.layout || '').trim();
  if (NP_CAP_LAYOUTS.some(x => x.k === layout)) out.layout = layout;
  const mark = String(o.mark || '').trim();
  if (NP_MARK_MODES.indexOf(mark) >= 0) out.mark = mark;
  const markText = String(o.markText == null ? '' : o.markText).trim().slice(0, 60);
  if (markText) out.markText = markText;
  const markImg = String(o.markImg || '');
  if (/^data:image\//.test(markImg)) out.markImg = markImg;
  const markPos = String(o.markPos || '').trim();
  if (markPos === 'br' || markPos === 'bl') out.markPos = markPos;
  if (o.classify) out.classify = true;
  return out;
}


function npLookToken(look) {
  const l = npLookShape(look);
  return NP_LOOK_AXES.filter(a => a.k !== 'mark').map(a => l[a.k]).filter(Boolean).join('；');
}
 



