const NP_NO_REAL_LINE = '【画风】整张图统一用一种画法：人物、背景、道具、其他人都按画的处理，不要真人照片、不要写实摄影、不要混进真实皮肤和布料质感。';
const NP_THEME_TONE = { '暗调暖光·单一光源': '暗调、单一暖光', '暗调实拍·单一暖光源': '暗调、单一暖光' };
function npThemeTone(t) {
  const v = String(t || '').trim();
  if (!v) return '';
  return NP_THEME_TONE[v] || v.replace(/[·•＋+]/g, '、');
}
function npShotStyle(look) {
  const l = npLookShape(look);
  const b = String(l.born || '').trim();
  const st = Object.assign({}, NP_SHOT_STYLE[b] || NP_STYLE_FALLBACK);
  if (b) st.tag = b;
  if (b === '广告片') {
    const tone = npThemeTone(l.theme);
    if (tone) st.rules = String(st.rules || '') + '色调：' + tone + '。';
  }
  return st;
}
const NP_STUDIO_HINT = /影棚|棚拍|摄影棚|布光|打光|补光|主光|辅光|轮廓光|柔光箱|反光板|背景纸|纯色背景|大光圈|景深|单反|微单|电影感|广告大片|质感大片|镜头光晕|丁达尔|伦勃朗|侧逆光|顶光|逆光|侧光|光从|光源|碘钨灯|灯架|摄影灯|闪光灯|布景|色温/;
 
function npStripStudioHints(s) {
  return String(s || '').split(/(?<=[。！？!?；;])/).map(sent => {
    if (!NP_STUDIO_HINT.test(sent)) return sent;
    const keep = sent.split(/[，,]/).filter(cl => !NP_STUDIO_HINT.test(cl))
      .map(cl => cl.replace(/[。！？!?；;]+$/, ''));
    const body = keep.join('，').replace(/[，,]+$/, '');
    return body + (body ? '。' : '');
  }).join('').replace(/[，,；;]+。/g, '。').replace(/。。+/g, '。').trim();
}
 
function npShotCameraLine(w, it, i) {
  const st = npShotStyle(npLookOf(w));
  if (!st.camera) return '';
  const blob = String((it && it.topic) || '') + ' ' + npBriefVisual(it) + ' ' + npBriefBg(it, st, w);
  if (st.tag === '广告片') {
    if (/蹲|地上|地面|铺砖现场|墙角/.test(blob)) return '【机位】略低机位，贴地拍，主体占下半，背景压暗。';
    if (/桌|台面|报价单|料单|单子|本子|屏幕|键盘/.test(blob)) return '【机位】45 度俯拍，台面占下半，主体摆正中。';
    if (/门口|楼道|门框|单元/.test(blob)) return '【机位】三脚架平视，主体居中，背景干净有层次。';
    const ads = ['三脚架平视，主体居中，背景干净有层次', '45 度侧俯，主体占画面下半，背景压暗',
      '略低机位，主体显得挺拔，背景干净', '近景特写，主体占画面三分之二，背景虚化'];
    return '【机位】' + ads[i % ads.length] + '。';
  }
  if (st.tag !== '手机随拍') return '';
  if (/蹲|地上|地面|铺砖现场|墙角/.test(blob)) {
    return '【机位】手机在膝盖高，蹲下来离一米左右拍，竖拍，前景带一点杂物。';
  }
  if (/桌|台面|报价单|料单|单子|本子|屏幕|键盘/.test(blob)) {
    return '【机位】手机在桌边' + (i % 2 ? '斜上方 45 度' : '俯拍') + '，离桌面四五十厘米，竖拍，桌面占大半，手从画面边上伸进来。';
  }
  if (/门口|楼道|门框|单元/.test(blob)) {
    return '【机位】手机在门口离两米左右往里拍，竖拍，画面带一点门框或门口杂物。';
  }
  const ppl = ['手机在侧后方，齐胸口高，离一米半，竖拍，人物偏在画面一边，不摆姿势',
    '手机举到眼睛高，隔着半步拍，人物侧身、没看镜头',
    '手机在侧前方略低，离一米左右，拍到半身和手上的动作'];
  return '【机位】' + ppl[i % ppl.length] + '。';
}
 
