const NP_SCHEMA_VER = 2;
function npArchiveCoerce(old) {
  if (!old || typeof old !== 'object') return null;
  return Object.assign({}, old, {
    
    _sv: NP_SCHEMA_VER, dir: old.dir || 'old',
    kOut: old.kOut || '', dOut: old.dOut || '',
    voiceUrl: old.voiceUrl || '',
    voiceError: old.voiceError || null,
    dgenDocs: Array.isArray(old.dgenDocs) ? old.dgenDocs : [],
    dgen: (old.dgen && typeof old.dgen === 'object' && Array.isArray(old.dgen.segs)) ? old.dgen : null,
    asm: old.asm || null,
    
    queueNotes: Array.isArray(old.queueNotes) ? old.queueNotes : [],
    
    imgMotifs: Array.isArray(old.imgMotifs) ? old.imgMotifs : [],
    stagePlan: (old.stagePlan && typeof old.stagePlan === 'object') ? old.stagePlan : null,
    
    collectionIds: Array.isArray(old.collectionIds) ? old.collectionIds.filter(x => typeof x === 'string') : [],
    
    stats: (old.stats && typeof old.stats === 'object') ? old.stats : null,
    statsAt: Number(old.statsAt) || 0,
    url: String(old.url || ''),
    status: (old.status === '待发') ? '代发' : old.status,   
    
    
    
    fkind: String(old.fkind || ''),
    fSeed: Array.isArray(old.fSeed) ? old.fSeed.map(x => String(x == null ? '' : x)) : null,
    fSegs: Array.isArray(old.fSegs) ? old.fSegs.map(g => (Array.isArray(g) ? g.map(x => String(x == null ? '' : x)) : [String(g == null ? '' : g)])) : null,
    fGate: String(old.fGate || ''),
    fStyle: String(old.fStyle || ''),
    fImgs: Array.isArray(old.fImgs) ? old.fImgs : [],
    fVers: npFacadeVersCoerce(old.fVers),
    fCover: (old.fCover && typeof old.fCover === 'object') ? old.fCover : null,
    fSub: String(old.fSub || ''),
    fSubJob: (old.fSubJob && typeof old.fSubJob === 'object') ? old.fSubJob : null,
    pinned: !!old.pinned,
    pinAt: Number(old.pinAt) || 0,
  });
}



async function npNotesMigrate() {
  let touched = 0;
  await npNotesSync(async () => {
    const list = await npNotesAll();
    let dirty = false;
    const out = list.map(n => {
      if (!n || typeof n !== 'object') return n;
      const sv = Number(n._sv) || 0;
      if (sv >= NP_SCHEMA_VER) return n;     
      dirty = true; touched++;
      return npArchiveCoerce(n);
    });
    if (dirty) try { await chrome.storage.local.set({ [NP_NOTES_KEY]: out }); } catch (_) {}
  });
  return touched;
}
 
