    verify: { ico: '📱', txt: meta.ico + ' 要输验证码', btn: '去输验证码' },
    login: { ico: '🔐', txt: meta.ico + ' 没登录', btn: '去扫码' },
    perm: { ico: '🔑', txt: meta.ico + ' 差一次授权', btn: '去授权' },
    nostart: { ico: '🤖', txt: '已派出 · 机器人没回话', btn: '🔄 重派' },
