const NP_GATE_SHOTS = ['拍：你站在干活的地方，对着镜头', '拍：讲到哪一处就指哪一处', '拍：手上正在干活的那一下'];
 
function npFacGateData(f) {
  return { arId: f.arId, title: f.title, script: npFacadeText(f), sents: npFacadeScreens(f), lip: f.lip || null,
    film: f.film || null, mode: 'f',
    land: async () => { await npFacadeSave(); return { arId: f.arId, title: f.title, script: npFacadeText(f) }; } };
}
function npFacadeScreens(f) {
  const out = [];
  (f.segs || []).forEach(seg => (seg || []).forEach(t => {
    const txt = String(t || '').trim();
    if (txt) out.push(txt);
  }));
  return out;
}
 
const NP_SELF_CAP = 250;
 
function npSentsOf(script) {
  return npSplitSents(script).filter(x => x && x.t).map(x => String(x.t).trim()).filter(Boolean);
}
 
async function npGateAction(cmd, d, after) {
  const a = d || {}, l = a.lip || {};
  if (cmd === 'selfopen') {
    const out = await npGateSelfOpen(a);
    if (!out) return;
    if (typeof after === 'function') after(out.lip);
    if (typeof toast === 'function') toast(out.fresh ? '逐句录的链接好了——手机上开这一条，一句一句念' : '这一篇早就有这条链接，接着念就行');
    return;
  }
  if (cmd === 'selfview') {
    const u = lipRecordUrl(l);
    if (!u) { if (typeof toast === 'function') toast('还没拿链接——先点上面那颗「🎥 拿逐句录的链接」', 'error'); return; }
    window.open(u, '_blank');
    return;
  }
  if (cmd === 'selfcopy') {
    const u = lipRecordUrl(l);
    if (!u) { if (typeof toast === 'function') toast('还没拿链接——先点上面那颗「🎥 拿逐句录的链接」', 'error'); return; }
    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(u).then(
      () => { if (typeof toast === 'function') toast('链接抄好了——发到你自己手机上，用浏览器打开就能一句一句录'); },
      () => { if (typeof toast === 'function') toast('抄没成——在上面那条链接里全选复制', 'error'); });
    return;
  }
  if (cmd === 'orderopen') {
    let arId = String(a.arId || ''), title = String(a.title || ''), script = String(a.script || '');
    if (l && l.id && l.route === 'avatar' && l.state !== 'canceled') { npLipView(arId, l); return; }
    if (typeof a.land === 'function') {               
      const got = await a.land();
      if (got) { arId = String(got.arId || arId); title = String(got.title || title); script = String(got.script || script); }
    }
    npLipOpen({ arId: arId, title: title, script: script, route: 'avatar' });
    return;
  }
}
 
async function npGateSelfOpen(d) {
  const script = String(d.script || '').trim();
  if (!script) { if (typeof toast === 'function') toast('稿子是空的——先出稿再拿链接', 'error'); return null; }
  const cn = lipCount(script);
  if (cn > NP_SELF_CAP) {
    if (typeof toast === 'function') toast('现在 ' + cn + ' 字，自己念这一条上限 ' + NP_SELF_CAP + ' 字——先砍 ' + (cn - NP_SELF_CAP) + ' 字（念下来约 ' + Math.round(cn / 4.6) + ' 秒，太长压不住）', 'error');
    return null;
  }
  let arId = String(d.arId || ''), title = String(d.title || '');
  if (typeof d.land === 'function') {
    const got = await d.land();
    if (got) { arId = String(got.arId || arId); title = String(got.title || title); }
  }
  if (!arId) { if (typeof toast === 'function') toast('这一篇还没进档案——先存一下再拿链接', 'error'); return null; }
  let r = null;
  try {
    r = await lipApi('/api/lip/submit', { route: 'self', script: script, noteId: arId, title: title, segs: npSentsOf(script) });
  } catch (e) {
    if (typeof toast === 'function') toast('链接没挂上云端：' + ((e && e.message) || '网络不通'), 'error');
    return null;
  }
  const job = r && r.job;
  if (!job) { if (typeof toast === 'function') toast((r && r.error) || '链接没挂上——再点一次', 'error'); return null; }
  const peel = lipPeel(job);
  await lipPatch(arId, peel);
  return { arId: arId, lip: peel, fresh: !!r.ok };
}

 
const NP_UP_FILM_MAX = 200 * 1024 * 1024;
const NP_UP_FILM_SECS = 180.5;
const NP_UP_SUB_MAX = 100 * 1024 * 1024;
const NP_UP_SUB_CHARS = 900;

 
function npGateFilmCheck(file) {
  if (!file || !file.size) return '这个文件是空的——重新选一次';
  const mime = String(file.type || '').toLowerCase();
  const name = String(file.name || '').toLowerCase();
  const okMime = /^video\/(mp4|quicktime|webm|x-matroska)$/.test(mime);
  const okExt = /\.(mp4|mov|webm|mkv)$/.test(name);
  if (!okMime && !okExt) return '只收 mp4 / mov / webm / mkv 这几种视频';
  if (file.size > NP_UP_FILM_MAX) return '这条片 ' + (file.size / 1048576).toFixed(0) + 'MB，最大 200MB——先压一下再传（这一版不做压缩）';
  return '';
}
 
function npGateFilmProbe(url) {
  return new Promise((res, rej) => {
    const v = document.createElement('video');
    v.preload = 'metadata'; v.muted = true;
    let done = false;
    const fin = (fn, x) => { if (done) return; done = true; clearTimeout(tm); try { v.removeAttribute('src'); v.load(); } catch (_) {} fn(x); };
    const tm = setTimeout(() => fin(rej, new Error('读不出时长（文件太大或编码这台浏览器认不了）')), 6000);
    v.onloadedmetadata = () => { const d = Number(v.duration); if (d && isFinite(d) && d > 0) fin(res, d); else fin(rej, new Error('这条视频读不出时长')); };
    v.onerror = () => fin(rej, new Error('这台浏览器播不动这个格式'));
    v.src = url;
  });
}
 
async function npFilmPatch(arId, meta) {
  const id = String(arId || '');
  if (!id) return null;
  return npNotesSync(async () => {
    const list = await npNotesAll();
    const n = list.find(x => x && String(x.id) === id);
    if (!n) return null;
    n.fFilm = meta ? {
      name: String(meta.name || ''), size: Number(meta.size) || 0, dur: Number(meta.dur) || 0,
      at: Number(meta.at) || Date.now(), src: String(meta.src || 'upload'), decodeFail: !!meta.decodeFail,
    } : null;
    n.fSub = ''; n.fSubJob = null;
    n.updatedAt = Date.now();
    try { await chrome.storage.local.set({ [NP_NOTES_KEY]: list }); } catch (_) {}
    return n;
  });
}
 
async function npGateFilmUpload(file, mode) {
  const bad = npGateFilmCheck(file);
  if (bad) { if (typeof toast === 'function') toast(bad, 'error'); return; }
  let dur = 0, decodeFail = false;
  const objUrl = URL.createObjectURL(file);
  try { dur = await npGateFilmProbe(objUrl); } catch (_) { decodeFail = true; }
  try { URL.revokeObjectURL(objUrl); } catch (_) {}
  if (!decodeFail && dur > NP_UP_FILM_SECS) {
    if (typeof toast === 'function') toast('这条片 ' + dur.toFixed(1) + ' 秒，最长 3 分钟——先剪短一点再传', 'error');
    return;
  }
  const d = mode === 'k' ? npKGateData(_npWiz) : (_npFac ? npFacGateData(_npFac) : null);
  if (!d) { if (typeof toast === 'function') toast('这一篇还没打开——回档案重新点一次', 'error'); return; }
  let arId = String(d.arId || '');
  let exists = false;
  if (arId) { try { exists = !!(await npArFindById(arId)); } catch (_) {} }
  if (!exists && typeof d.land === 'function') {
    const got = await d.land();
    if (got) arId = String(got.arId || arId);
  }
  if (!arId) { if (typeof toast === 'function') toast('这一篇还没进档案——先存一下再传', 'error'); return; }
  const meta = {
    name: String(file.name || '整条视频').slice(0, 80), size: file.size,
    dur: decodeFail ? 0 : dur, at: Date.now(), src: 'upload', decodeFail: !!decodeFail,
  };
  try { await npCasePut('film:' + arId, file); }
  catch (e) { if (typeof toast === 'function') toast('整条片存不进本机：' + String((e && e.message) || ''), 'error'); return; }
  const staged = await npPubStageFiles(arId, [file], true);
  await npFilmPatch(arId, meta);
  if (mode === 'f' && _npFac && String(_npFac.arId) === arId) {
    _npFac.film = meta; _npFac.sub = ''; _npFac.subJob = null;
    npFacCvDrop(arId);
    if (_npFac.step < 4) { _npFac.step = 4; npFacStationReset(_npFac); }
    await npFacadeSave();
    npFacadePaint(_npActiveContainer);
  }
  if (mode === 'k') {
    if (_npWiz) {
      _npWiz.fFilm = meta;
       
      if (String((_npWiz.draft && _npWiz.draft.content) || '').trim()) {
        const gate = String(_npWiz.kGate || 'talk');
        await npKFinishBase('voice', 'voice', (x) => { x.fGate = gate; x.fFilm = meta; });
      }
    }
    switchMainTab('noteArchive');
  }
  if (typeof toast === 'function') {
    toast(decodeFail
      ? '整条片收好了——这台浏览器解不开画面，封面那一站传一张自己的图就行，片子照发'
      : '整条片收好了（' + (file.size / 1048576).toFixed(1) + 'MB' + (dur > 0 ? ' · ' + dur.toFixed(1) + ' 秒' : '') + '）' + (staged ? '——去挑封面，不挑也能先在档案里播' : '；「代发区」那份没塞进去，发布前再传一次'));
  }
}
 
function npGatePutWhole(job, blob, onPct) {
  return new Promise((res, rej) => {
    const qs = 'job=' + encodeURIComponent(job.id) + '&part=whole&t=' + encodeURIComponent(job.token) +
      '&name=' + encodeURIComponent(String(blob.name || '成片.mp4')) + '&mime=' + encodeURIComponent(String(blob.type || 'video/mp4'));
    const xhr = new XMLHttpRequest();
    xhr.open('POST', '/api/lip/put?' + qs);
    xhr.setRequestHeader('Content-Type', String(blob.type || 'video/mp4'));
    xhr.upload.onprogress = (e) => { if (e.lengthComputable && typeof onPct === 'function') onPct(Math.round(e.loaded / e.total * 100)); };
    xhr.onload = () => {
      let r = null; try { r = JSON.parse(xhr.responseText || '{}'); } catch (_) {}
      if (xhr.status >= 200 && xhr.status < 300 && r && r.ok !== false) res(r);
      else rej(new Error((r && r.error) || ('HTTP ' + xhr.status)));
    };
    xhr.onerror = () => rej(new Error('网络断了——整条片没传完'));
    xhr.onabort = () => rej(new Error('上传被中断了'));
    xhr.send(blob);
  });
}







