  return '<span class="npar-pf" style="' + lipTone(l.state) + '" title="' +
    npArAttr(l.route === 'self' ? '逐句录：' + ((LIP_LAB_SELF[String(l.state)] || '进行中') + '（录了 ' + (l.segGot || 0) + '/' + (l.segCount || 0) + ' 句）')
      : '口播工单：' + lipLab(l.state, l.route) + (l.dueAt ? '，说好 ' + lipDue(l.dueAt) + ' 前片回来' : '')) + '">' + t + '</span>';
