      const arr = f.segs[parseInt(p[0], 10) || 0] || [];
      arr[parseInt(p[1], 10) || 0] = String(arr[parseInt(p[1], 10) || 0] || '');
      f.open = k; f.own = k; npFacadePaint(container);
      const box = _npEl(container, 'npFacBody');
