function npFacCopy(text, msg) {
  const t = String(text || '').trim();
  if (!t) { if (typeof toast === 'function') toast('这一格还没东西可复制'); return; }
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(t).then(
      () => { if (typeof toast === 'function') toast(msg || '复制好了'); },
      () => { if (typeof toast === 'function') toast('复制没成——在那一格全选复制'); });
  } else if (typeof toast === 'function') toast('复制没成——在那一格全选复制');
}






const NP_NEED_KEY = 'np_asset_needs';       
const NP_ASSETS_KEY = 'np_assets';          

let _npAsFocus = [];       
let _npAsBusy = false;
let _npAsUpCol = '';       
let _npAsDelegated = false;
let _npAsNew = false;      
let _npAsNewDesc = '';     
let _npAsNewPicked = [];   
let _npAsColl = null;      
let _npAsQ = '';           
let _npAsContainer = null; 
let _npClipsCache = [];    
 
let _npAsTab = 'cfg';      
let _npAsChk = false;      
let _npAsNewKind = '';     
let _npAsNewUse = 'ask';   
let _npAsEdit = '';        
let _npAsEditKindOnly = 0; 
let _npAsEditDraft = null; 

async function npAsAssetsRead() {
  try {
    const d = await chrome.storage.local.get(NP_ASSETS_KEY);
    const a = d[NP_ASSETS_KEY];
    if (Array.isArray(a)) return a;
  } catch (_) {}
  return [];
}
async function npAsAssetsWrite(list) { try { await chrome.storage.local.set({ [NP_ASSETS_KEY]: list }); } catch (_) {} }

 
async function npAsTitlePools() {
  const sellTitles = [], kbTitles = [];
  try {
    const c = await readConfigPlain();
    ((c && c.product && c.product.sellPoints) || []).forEach(s => {
      const t = String((s && s.title) || '').trim();
      if (t) sellTitles.push(t);
    });
  } catch (_) {}
  try {
    const r = await chrome.runtime.sendMessage({ action: 'getKnowledgeBase' });
    ((r && r.entries) || []).forEach(e => {
      if (!e || e.isActive === false) return;
      const t = String(e.title || '').trim();
      if (t) kbTitles.push(t);
    });
  } catch (_) {}
  return { sellTitles, kbTitles };
}

 
function npAsClassifySource(source, sellTitles, kbTitles) {
  const s = String(source || '').trim();
  if (!s) return '';
  const pick = (arr) => arr.find(t => t && (t === s || s.includes(t) || t.includes(s)));
  const sp = pick(sellTitles); if (sp) return 'sell|' + sp;
  const kb = pick(kbTitles); if (kb) return 'kb|' + kb;
  return '';
}

function npAsColItems(colId) { return (_npClipsCache || []).filter(c => c && c.col === colId); }

 
async function npAsGapsFor(notes) {
  const gaps = {};
  if (!notes || !notes.length) return gaps;
  const cols = await npCollectionsRead();
  if (!cols.length) return gaps;
  const clips = await npClipsRead();
  const cnt = {};
  clips.forEach(c => { if (c && c.col) cnt[c.col] = (cnt[c.col] || 0) + 1; });
  const hitOne = (p, n) => {
    const nm = String(p[1] || '').trim();
    if (!nm) return false;
    if (p[0] === 'sell') return (n.sellPoints || []).some(x => { const s = String((x && x.point) || '').trim(); return !!s && (s === nm || s.includes(nm) || nm.includes(s)); });
    return (n.kb || []).some(e => { const s = String((e && (e.title || e.id)) || '').trim(); return !!s && (s === nm || s.includes(nm) || nm.includes(s)); });
  };
  notes.forEach(n => {
    const hit = [];
    cols.forEach(col => {
      if (npAsUseOf(col) !== 'on') return;
      const p = String(col.source || '').split('|');
      if (p[0] !== 'sell' && p[0] !== 'kb') return;
      if (!hitOne(p, n)) return;
      if (cnt[col.id]) return;   
      hit.push({ id: col.id, title: String(col.name || '') });
    });
    if (hit.length) gaps[n.id] = hit;
  });
  return gaps;
}

 
function npAsGapText(hit) {
  const arr = hit || [];
  return '还缺 ' + arr.length + ' 项（' + arr.slice(0, 2).map(x => x.title).filter(Boolean).join('、') + (arr.length > 2 ? ' 等 ' + arr.length + ' 条' : '') + '）';
}




async function npAssetsMigrate() {
  let v = null;
  try { v = (await chrome.storage.local.get(NP_NEED_KEY))[NP_NEED_KEY]; } catch (_) {}
  const needs = (v && Array.isArray(v.needs)) ? v.needs : [];
  if (!needs.length) return 0;
  const pools = await npAsTitlePools();
  const cols = await npCollectionsRead();
  const clips = await npClipsRead();
  const assets = await npAsAssetsRead();
  const byName = {};
  cols.forEach(c => { if (c && c.name && byName[c.name] === undefined) byName[c.name] = c; });
  const colOf = {};
  let n = 0;
  needs.forEach(x => {
    if (!x || !x.title) return;
    const title = String(x.title).trim();
    if (!title) return;
    const key = x.id || ('t:' + title);
    if (byName[title]) { colOf[key] = byName[title].id; return; }
    const col = {
      id: npCollectionId(),
      name: title.slice(0, 30),
      desc: String(x.spec || '').trim(),
      source: x.manual ? '自己加的' : npAsClassifySource(x.source, pools.sellTitles, pools.kbTitles),
      manual: !!x.manual,
      link: (x.manual && x.link) ? x.link : null,
      at: x.createdAt || Date.now(),
    };
    cols.push(col);
    byName[col.name] = col;
    colOf[key] = col.id;
    n++;
  });
  const have = new Set(clips.map(c => c && c.id));
  assets.forEach(a => {
    if (!a || !a.id || !a.needId || have.has(a.id)) return;
    const col = colOf[a.needId];
    if (!col) return;
    clips.push({
      id: a.id, col: col, imgOnly: true,
      src: String(a.name || a.ref || '本机图'),
      stage: '', kb: null, vo: '', tags: [], fo: [],
      thumb: String(a.thumb || ''), w: a.w || 0, h: a.h || 0,
      ref: '', at: a.addedAt || Date.now(),
    });
    n++;
  });
  if (n) { await npCollectionsWrite(cols); await npClipsWrite(clips); }
  return n;
}

 
function npAsThumb(file) {
  return new Promise((resolve, reject) => {
    const fr = new FileReader();
    fr.onerror = () => reject(new Error('读文件失败'));
    fr.onload = () => {
      const img = new Image();
      img.onerror = () => reject(new Error('不是能识别的图片'));
      img.onload = () => {
        try {
          const MAX = 160;
          const iw = img.width || MAX, ih = img.height || MAX;
          const sc = Math.min(1, MAX / Math.max(iw, ih));
          const w = Math.max(1, Math.round(iw * sc)), h = Math.max(1, Math.round(ih * sc));
          const cv = document.createElement('canvas');
          cv.width = w; cv.height = h;
          cv.getContext('2d').drawImage(img, 0, 0, w, h);
          const thumb = cv.toDataURL('image/jpeg', 0.72);
          const done = (prev) => resolve({ thumb: thumb, w: iw, h: ih, prev: prev || null });
          try {
            const PREV = 1080;
            const psc = Math.min(1, PREV / Math.max(iw, ih));
            const pw = Math.max(1, Math.round(iw * psc)), ph = Math.max(1, Math.round(ih * psc));
            const pcv = document.createElement('canvas');
            pcv.width = pw; pcv.height = ph;
            pcv.getContext('2d').drawImage(img, 0, 0, pw, ph);
            pcv.toBlob(b => done(b), 'image/jpeg', 0.88);
          } catch (_) { done(null); }
        } catch (e) { reject(e); }
      };
      img.src = String(fr.result || '');
    };
    fr.readAsDataURL(file);
  });
}

 
function npAsPrevSave(aid, t) {
  if (!aid || !t || !t.prev) return Promise.resolve();
  return npCasePut('asprev:' + String(aid), t.prev).catch(() => {});
}

 
async function npAsFingerprint() {
  try {
    const c = await readConfigPlain();
    const sp = ((c && c.product && c.product.sellPoints) || [])
      .map(s => String((s && (s.title || s.content)) || '').trim().slice(0, 30)).filter(Boolean);
    let kb = [];
    try {
      const r = await chrome.runtime.sendMessage({ action: 'getKnowledgeBase' });
      kb = ((r && r.entries) || []).filter(e => e && e.isActive !== false)
        .map(e => String(e.title || '').trim()).filter(Boolean).slice(0, 40);
    } catch (_) {}
    return [String((c && c.product && c.product.name) || '').trim(),
      ((c && c.product && Array.isArray(c.product.names)) ? c.product.names.slice(1) : []).join('、')]
      .concat(sp, kb).join('|');
  } catch (_) { return ''; }
}

 
async function npAsGen(container) {
  if (_npAsBusy) return;
  const fp = await npAsFingerprint();
  const meta = await npAsColMetaRead();
  const cols0 = await npCollectionsRead();
  if (fp && meta.sig === fp && cols0.length) { if (typeof toast === 'function') toast('卖点 / 知识库没变，集合还是上次那些'); return; }
  _npAsBusy = true;
  renderNoteAssets(container);
  try {
    const r = await chrome.runtime.sendMessage({ action: 'genAssetNeeds', data: {} });
    if (!r || r.ok === false || !Array.isArray(r.needs)) throw new Error((r && r.error) || 'AI 没给出素材集合');
    const cols = await npCollectionsRead();
    const have = new Set(cols.map(c => c && c.name).filter(Boolean));
    const pools = await npAsTitlePools();
    r.needs.forEach(x => {
      const title = String((x && x.title) || '').trim();
      if (!title || have.has(title)) return;
      cols.push({
        id: npCollectionId(),
        name: title.slice(0, 30),
        desc: String((x && x.spec) || '').trim(),
        source: npAsClassifySource((x && x.source) || '', pools.sellTitles, pools.kbTitles),
        manual: false, link: null, at: Date.now(),
      });
      have.add(title);
    });
    await npCollectionsWrite(cols);
    await npAsColMetaWrite({ sig: fp, genAt: Date.now() });
    if (typeof toast === 'function') toast('AI 把还没料的集合列出来了——空着的传上图就补上');
  } catch (e) {
    if (typeof toast === 'function') toast('整理素材失败：' + String((e && e.message) || e), 'error');
  }
  _npAsBusy = false;
  renderNoteAssets(container);
}





async function npAsKindFingerprint() {
  const base = await npAsFingerprint();
  let extra = '';
  try {
    const c = await readConfigPlain();
    const dz = (c && c.diagnosis) || {};
    extra = [String(dz.accountType || '').trim(),
      (Array.isArray(dz.answers) ? dz.answers : []).map(a => String((a && a.answer) || '').trim()).join('|')].join('#');
  } catch (_) {}
  return base + '@' + extra.slice(0, 1200);
}

async function npAsConfigKinds(container, opts) {
  if (_npAsBusy) return;
  const force = !!(opts && opts.force);
  _npAsBusy = true;
  renderNoteAssets(container);
  try {
    const cols = await npCollectionsRead();
    const clips = await npClipsRead();
    const cnt = {};
    clips.forEach(c => { if (c && c.col) cnt[c.col] = (cnt[c.col] || 0) + 1; });
    const st = await npAsKindStateRead();
    const fp = await npAsKindFingerprint();
    let usedAi = false;
    if (force || !fp || st.tried !== fp) {
      
      st.tried = fp;
      try { await npAsKindStateWrite(st); } catch (_) {}
      const r = await chrome.runtime.sendMessage({
        action: 'configAssetKinds',
        data: { cols: cols.map(c => ({ name: c.name, desc: c.desc, source: c.source, has: cnt[c.id] || 0 })) },
      });
      if (!r || r.ok === false || !r.kinds) throw new Error((r && r.error) || 'AI 没判出这 18 类');
      st.sig = fp; st.at = Date.now(); st.kinds = r.kinds;
      usedAi = true;
      
      const byName = {};
      (Array.isArray(r.cols) ? r.cols : []).forEach(x => { if (x && x.name && x.kind && !byName[x.name]) byName[x.name] = x.kind; });
      cols.forEach(c => { if (!c.kind) { const k = byName[String(c.name || '').trim()]; if (k) c.kind = k; } });
    }
    const stageTxt = (typeof _ntStageName === 'function' ? _ntStageName() : '') || '本阶段';
    let on = 0, off = 0, ask = 0, kept = 0;
    cols.forEach(c => {
      const cur = npAsUseOf(c);
      if (c.mine) { kept++; cur === 'on' ? on++ : cur === 'off' ? off++ : ask++; return; }
      const nv = AssetKinds.useVerdict({
        v: c.kind ? npAsKindV(st, c.kind) : '',
        why: npAsKindWhy(st, c.kind),
        has: cnt[c.id] || 0, source: c.source, stageTxt: stageTxt,
      });
      c.use = nv.use; c.why = nv.why;
      nv.use === 'on' ? on++ : nv.use === 'off' ? off++ : ask++;
    });
    
    let opened = 0;
    NP_ASSET_KINDS.forEach(x => {
      if (npAsKindV(st, x.k) !== 'need') return;
      if (cols.some(c => c && c.kind === x.k)) return;
      cols.push({
        id: npCollectionId(), name: x.n, desc: x.need, source: '自己加的', manual: true, link: null,
        kind: x.k, use: 'ask', why: 'AI 判这一类该备，这一集是刚开的空集合——传图进去就补上', at: Date.now(),
      });
      opened++; ask++;
    });
    await npCollectionsWrite(cols);
    await npAsKindStateWrite(st);
    _npAsFocus = [];
    if (typeof toast === 'function') {
      toast('AI 配完：用 ' + on + ' · 停用 ' + off + ' · 还没定 ' + ask +
        (kept ? '（你改过的 ' + kept + ' 条没动）' : '') +
        (opened ? '；新开空集合 ' + opened + ' 个' : '') +
        (usedAi ? '' : '（诊断与卖点没变，只重推了用不用）'));
    }
  } catch (e) {
    if (typeof toast === 'function') toast('配置集合失败：' + String((e && e.message) || e), 'error');
  }
  _npAsBusy = false;
  renderNoteAssets(container);
}

 
async function npAsSetKindV(k, v) {
  const st = await npAsKindStateRead();
  if (!npAssetKindOf(k)) return;
  const ai = st.kinds && st.kinds[k] && st.kinds[k].v;
  const back = (v === 'gray' && npAsGrayKind(k) && !ai) || v === ai;
  if (back) delete st.own[k]; else st.own[k] = v;
  await npAsKindStateWrite(st);
}

 
async function npAsSetColUse(container, id, u) {
  const cols = await npCollectionsRead();
  const col = cols.find(x => x && x.id === id);
  if (!col) return;
  col.use = (u === 'on' || u === 'off' || u === 'ask') ? u : 'ask';
  col.mine = 1;
  await npCollectionsWrite(cols);
  renderNoteAssets(container);
  if (typeof toast === 'function') toast('「' + esc(String(col.name || '')) + '」' +
    (col.use === 'on' ? '启用了——参与挑料、报缺口' : col.use === 'off' ? '停用了——里面的料还在，不算缺' : '标成还没定'));
}

 
async function npAsKindCycle(container, k) {
  const st = await npAsKindStateRead();
  const order = npAsGrayKind(k) ? ['gray', 'need', 'no', 'ask'] : ['need', 'no', 'ask'];
  const next = order[((order.indexOf(npAsKindV(st, k)) + 1) % order.length + order.length) % order.length];
  await npAsSetKindV(k, next);
  renderNoteAssets(container);
}

 
