async function npCaseColFor(noteId, title) {
  const src = '剪段入库|' + noteId;
  const cols = await npCollectionsRead();
  let col = cols.filter(c => c && c.source === src)[0];
  const nm = String(title || '').replace(/（还没定名）$/, '').trim();
  if (!col) {
    col = { id: npCollectionId(), name: nm || '案例剪段', desc: '案例视频剪出来的段，按篇归档；点图墙的 ▶ 播这一段。', source: src, manual: false, link: null, at: Date.now() };
    cols.unshift(col);
    await npCollectionsWrite(cols);
  } else if (nm && col.name !== nm) {
    col.name = nm;
    await npCollectionsWrite(cols);
  }
  return col;
}
async function npCaseColRename(noteId, title) {
  const nm = String(title || '').replace(/（还没定名）$/, '').trim();
  if (!nm) return;
  const cols = await npCollectionsRead();
  const col = cols.filter(c => c && c.source === '剪段入库|' + noteId)[0];
  if (!col || col.name === nm) return;
  col.name = nm;
  await npCollectionsWrite(cols);
}
async function npCasePushClip(noteId, title, m, s) {
  if (!noteId || !m || !s) return '';
  if (_npCase && _npCase.libMode) return '';   
  const col = await npCaseColFor(noteId, title);
  const dur = Number(m.dur) || 0;
  const a = Math.round(s.a / 100 * dur * 100) / 100;
  const b = Math.round(s.b / 100 * dur * 100) / 100;
  const stage = (s.stage && s.stage !== '🌫') ? String(s.stage) : '过渡';
  const mute = stage === '过渡';
  const vo = mute ? '' : String(s.vo || '');
  const ref = 'mat:' + noteId + ':' + m.id;
  const clips = await npClipsRead();
  const hit = clips.filter(c => c && c.col === col.id && c.ref === ref &&
    Math.abs((Number(c.a) || 0) - a) < 0.06 && Math.abs((Number(c.b) || 0) - b) < 0.06)[0];
  if (hit) {
    hit.stage = stage;
    hit.vo = vo;
    hit.kb = mute ? null : (s.kb || null);
    hit.dur = Math.max(1, Math.round(b - a));
    await npClipsWrite(clips);
    return col.name;
  }
  const clip = {
    id: npClipId(), col: col.id, imgOnly: false, src: String(m.name || '案例视频'),
    a: a, b: b, dur: Math.max(1, Math.round(b - a)), stage: stage, kb: mute ? null : (s.kb || null), vo: vo,
    tags: ['案例'], fo: ['待标'], thumb: '', w: 0, h: 0, ref: ref, at: Date.now(),
  };
  clips.unshift(clip);
  await npClipsWrite(clips);
  if (m.blob) npClipGrabThumb(clip.id, m.blob, a + 0.1).catch(() => {});
  return col.name;
}
 
function npClipGrabThumb(clipId, blob, at) {
  return new Promise((res) => {
    let video = null, url = '', done = false;
    const fin = (thumb, w, h) => {
      if (done) return; done = true;
      if (url) { try { URL.revokeObjectURL(url); } catch (_) {} }
      if (video) { try { video.removeAttribute('src'); video.load(); } catch (_) {} }
      if (!thumb) { res(false); return; }
      npClipsRead().then(list => {
        const c = list.filter(x => x && x.id === clipId)[0];
        if (c && !c.thumb) { c.thumb = thumb; c.w = w; c.h = h; return npClipsWrite(list); }
      }).then(() => res(true)).catch(() => res(true));
    };
    try {
      if (!blob) { res(false); return; }
      url = URL.createObjectURL(blob);
      video = document.createElement('video');
      video.muted = true; video.preload = 'metadata';
      const tm = setTimeout(() => fin('', 0, 0), 8000);
      video.onloadedmetadata = () => {
        const d = Number(video.duration) || 0;
        const target = Math.max(0.1, Math.min(Number(at) || 0.1, Math.max(0.1, d - 0.05)));
        try { video.currentTime = target; } catch (_) { clearTimeout(tm); fin('', 0, 0); }
      };
      video.onseeked = () => {
        clearTimeout(tm);
        try {
          const iw = video.videoWidth, ih = video.videoHeight;
          if (!iw || !ih) { fin('', 0, 0); return; }
          const sc = Math.min(1, 320 / Math.max(iw, ih));
          const cv = document.createElement('canvas');
          cv.width = Math.max(1, Math.round(iw * sc));
          cv.height = Math.max(1, Math.round(ih * sc));
          cv.getContext('2d').drawImage(video, 0, 0, cv.width, cv.height);
          fin(cv.toDataURL('image/jpeg', 0.72), iw, ih);   
        } catch (_) { fin('', 0, 0); }
      };
      video.onerror = () => { clearTimeout(tm); fin('', 0, 0); };
      video.src = url;
    } catch (_) { fin('', 0, 0); }
  });
}




let _npLibView = { view: 'lib', colId: '', videoId: '', segId: '', batchId: '', folderId: '', surface: 'assets', q: '', tags: [], libFolder: '', noTag: false, picked: [] };
let _npLibCtx = null;
let _npLibCache = { cols: [], videos: [], clips: [], notes: [], batches: [] };
