  const def = surface === 'bench' ? 'bench' : 'lib';
  
  const edAlive = !!(v && v.view === 'editor' && _npLibEditor && String(_npLibEditor.videoId) === String(v.videoId || ''));
  if (!v || (v.view === 'editor' && !edAlive)) {
    st.view = def;
    st.videoId = ''; st.segId = ''; st.batchId = ''; st.folderId = ''; st.colId = '';
    return;
  }
  st.view = v.view || def;
