  if (!ed) return false;
  const video = _npLibCache.videos.find(v => v && String(v.id) === String(ed.videoId));
  const dur = Number(video && video.dur) || 0;
  const tt = Math.round(Number(t) * 10) / 10;
  if (!(dur > 1) || !(tt > 0.3 && tt < dur - 0.3)) return false;
